   JOIN Stor_Cod_Model  Mdl  ON Trn.Model_Id =     Mdl.Id
   JOIN Stor_Cod_Color  Clr  ON Trn.Color_Id =     Clr.Id
   JOIN Stor_Cod_Size   Siz  ON Trn.Size_Id  =     Siz.Id;

